"""Independent spoken and measured review of the upper unit semicircle, chapter XII questions 1–7 (p. 290)."""
import argparse
import json
from math import acos, degrees, sqrt
from trigonometric_rays import radial, simplify_polar_labels
from upper_semicircle import BOOK, ROOT, arc, author

OUT=ROOT/'geometry-course/textbook/data/trigonometry-review.json'


def review_entry(entry, n, title, *, part=None):
    page=290 if n<=7 else 291
    index='абв'.index(part)+1 if part else 1
    entry['id']=f'atanasyan-7-9-selfcheck-chapter-12-{n}-part-{index}'
    entry['title']=f'Вопрос {n}'+(part if part else '')+'. '+title
    entry['source'].update(collection='selfcheck',chapter='XII',exercise=str(n),printedPages=[page],pdfPages=[page+1])
    if part:entry['source']['subpart']=part
    entry['answer']={'mode':'manual','prompt':'Сформулируй доказательство или объяснение своим языком. Проверь его двумя числовыми заданиями и на изменённой модели.'}
    entry['review']['reviewer']=f'Точное соответствие вопросу {n}'+(part or '')+f' главы XII (издание Атанасяна 2023, с. {page}); авторское объяснение и новые варианты проверены по построениям.'
    return entry


def review(n,title,task,res,hint,steps,views,tests,refs,note=None):
    entry=author(n,None,[290],task,res,hint,steps,views,tests,refs,caption=note)
    return review_entry(entry,n,title)


def at(title,angle):
    return arc(title,[('M',angle)],edges=[('O','M')],projections=[('M','H')])


def endpoints(title,refs):
    return arc(title,edges=[('O',p) for p in refs])


def pair(title,p,q):
    return arc(title,[('M',p),('N',q)],edges=[('O','M'),('O','N'),('M','N')],projections=[('M','H'),('N','K')])


