def polar():
    views=[radial('Точка A на луче длины четыре',4,60,True),radial('Луч перешёл во вторую четверть',4,120,True),
           radial('Новая длина шесть и угол 150°',6,150,True)]
    entry=review(7,'Вычисли координаты по расстоянию и углу','У точки A неотрицательная ордината, OA=r>0. Луч OA образует угол α с положительной полуосью x. Выведи формулы обеих координат.',
        'На единичном луче M=(cos α;sin α). Векторы OA и OM сонаправлены, |OA|=r, |OM|=1. Значит, OA=r·OM и A=(r cos α;r sin α). При r=0 точка совпадает с O, направление луча не требуется.',
        'При переходе от M к A умножаются обе координаты. При тупом угле x отрицателен, хотя длина OA положительна.',[
        ('Сначала найди единичный образец','При 60° единичная точка M=(1/2;√3/2). Умножение на r=4 даёт A=(2;2√3).','Числа sin и cos определяют исходный единичный вектор.'),
        ('Поверни луч, сохрани длину','При 120° и r=4 знак абсциссы меняется: A=(−2;2√3). В обоих случаях x²+y²=16.','Длина r и положение относительно Oy отвечают за разные свойства.'),
        ('Примени обе замены','Пусть OA=6, α=150°. Тогда A=(−3√3;3). Масштаб увеличил обе исходные координаты одной и той же величиной.','Для проверки возведи обе координаты в квадрат и сложи.')],views,[
        ('Какова абсцисса при r=4 и α=120°?','-2','Умножь 4 на cos 120°=−1/2.'),
        ('Какова новая ордината при r=6 и α=150°?','3','Вычисли 6 sin 150°.')],[102],'Одна клетка равна одной единице. M — точка на единичной дуге, A — точка на том же луче на расстоянии r от O.')
    simplify_polar_labels(entry)
    return entry


def build():
    return {'bookId':BOOK,'lessons':first()+[polar()]}


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    out=json.dumps(build(),ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:
        assert OUT.read_text()==out
    else:
        OUT.write_text(out)
